import { serve } from 'https://deno.land/std@0.177.0/http/server.ts';
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';

// Helper to get allowed origin from environment
const getAllowedOrigin = () => {
  const publicUrl = Deno.env.get('PUBLIC_URL');
  const allowedUrl = Deno.env.get('ALLOWED_ORIGIN');
  return publicUrl || allowedUrl || 'http://localhost:3000';
};

serve(async (req) => {
  // Handle CORS preflight request
  if (req.method === 'OPTIONS') {
    const allowedOrigin = getAllowedOrigin();
    
    return new Response('ok', {
      headers: {
        'Access-Control-Allow-Origin': allowedOrigin,
        'Access-Control-Allow-Methods': 'POST, OPTIONS',
        'Access-Control-Allow-Headers':
          'Content-Type, Authorization, apikey, x-client-info',
      },
    });
  }

  try {
    if (req.method !== 'POST') {
      return new Response(JSON.stringify({ error: 'Method not allowed' }), {
        status: 405,
        headers: {
          'Content-Type': 'application/json',
          'Access-Control-Allow-Origin': getAllowedOrigin(),
        },
      });
    }

    const { code, cartTotal } = await req.json();

    if (!code) {
      return new Response(JSON.stringify({ error: 'Coupon code is required' }), {
        status: 400,
        headers: {
          'Content-Type': 'application/json',
          'Access-Control-Allow-Origin': getAllowedOrigin(),
        },
      });
    }

    // Initialize Supabase admin client
    const supabaseAdmin = createClient(
      Deno.env.get('SUPABASE_URL') ?? '',
      Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? '',
      { auth: { autoRefreshToken: false, persistSession: false } }
    );

    // Query coupon from database
    const { data: coupon, error } = await supabaseAdmin
      .from('coupons')
      .select('*')
      .eq('code', code.toUpperCase())
      .eq('active', true)
      .single();

    if (error || !coupon) {
      return new Response(JSON.stringify({ error: 'Invalid or expired coupon code' }), {
        status: 400,
        headers: {
          'Content-Type': 'application/json',
          'Access-Control-Allow-Origin': getAllowedOrigin(),
        },
      });
    }

    // Check if coupon has expired
    if (coupon.expires_at && new Date(coupon.expires_at) < new Date()) {
      return new Response(JSON.stringify({ error: 'Coupon has expired' }), {
        status: 400,
        headers: {
          'Content-Type': 'application/json',
          'Access-Control-Allow-Origin': getAllowedOrigin(),
        },
      });
    }

    // Check minimum cart value requirement
    if (coupon.min_cart_value && cartTotal && cartTotal < coupon.min_cart_value) {
      return new Response(JSON.stringify({ 
        error: `Minimum cart value of ₹${coupon.min_cart_value} required for this coupon` 
      }), {
        status: 400,
        headers: {
          'Content-Type': 'application/json',
          'Access-Control-Allow-Origin': getAllowedOrigin(),
        },
      });
    }

    // Calculate discount
    let discountAmount = 0;
    if (coupon.type === 'percent') {
      discountAmount = cartTotal ? (cartTotal * coupon.value) / 100 : 0;
      // Apply max discount limit if set
      if (coupon.max_discount_amount && discountAmount > coupon.max_discount_amount) {
        discountAmount = coupon.max_discount_amount;
      }
    } else if (coupon.type === 'flat') {
      discountAmount = coupon.value;
    }

    const allowedOrigin = getAllowedOrigin();

    return new Response(JSON.stringify({
      valid: true,
      coupon: {
        id: coupon.id,
        code: coupon.code,
        type: coupon.type,
        value: coupon.value,
        discountAmount,
        description: coupon.description,
        min_cart_value: coupon.min_cart_value,
        max_discount_amount: coupon.max_discount_amount,
        expires_at: coupon.expires_at,
      },
    }), {
      headers: {
        'Content-Type': 'application/json',
        'Access-Control-Allow-Origin': allowedOrigin,
        'Access-Control-Allow-Headers': 'Content-Type, Authorization',
      },
      status: 200,
    });

  } catch (error) {
    const allowedOrigin = getAllowedOrigin();
    
    return new Response(JSON.stringify({ error: error.message }), {
      headers: {
        'Content-Type': 'application/json',
        'Access-Control-Allow-Origin': allowedOrigin,
        'Access-Control-Allow-Headers': 'Content-Type, Authorization',
      },
      status: 500,
    });
  }
});
